var i=[{title:`Το πλαίσιο RAMP`,text:`Το RAMP σημαίνει Raise (ανεβάστε), Activate (ενεργοποιήστε), Mobilize (κινητοποιήστε) και Potentiate (ενισχύστε). Ανεβάστε τη θερμοκρασία του σώματος και την αναπνοή με ήπια δραστηριότητα, ξυπνήστε τους μυς που θα χρησιμοποιήσετε με ελεγχόμενες κινήσεις, κινηθείτε μέσα από τα εύρη που χρειάζεστε, και μετά κάντε πρόβα της άσκησης με σταδιακά υψηλότερη προσπάθεια που σας αφήνει ακόμη φρέσκους. Οι φάσεις μπορούν να επικαλύπτονται. Δεν χρειάζεται να είναι τέσσερα μεγάλα μπλοκ.`},{title:`Μια εκκίνηση πέντε έως δέκα λεπτών`,text:`Ξεκινήστε με ελαφρύ περπάτημα ή ποδηλασία. Προσθέστε ελεγχόμενες καθισιές με το σωματικό βάρος, αρθρώσεις ισχίου, κύκλους χεριών ή άλλες ασκήσεις που ταιριάζουν στη συνεδρία. Πριν από μια δύσκολη άσκηση, κάντε ένα ή περισσότερα ελαφρύτερα σετ προετοιμασίας με σταδιακή αύξηση. Πριν από διαλείμματα έντασης, ξεκινήστε με ευκολότερες εκδοχές της ίδιας κίνησης αντί να μπείτε κατευθείαν σε σπριντ.`},{title:`Προθερμανθείτε για τη δουλειά`,text:`Μια πίεση πάνω από το κεφάλι μπορεί να ζητά λίγη κίνηση του ώμου και ένα ελαφρύ σετ πίεσης. Ένα τρέξιμο μπορεί να ζητά ήπιο τζόκινγκ και μερικές σταδιακές επιταχύνσεις. Η βαριά ή τεχνική εργασία χρειάζεται συχνά περισσότερη προετοιμασία από ένα ήπιο περπάτημα. Ο στόχος είναι να αισθάνεστε έτοιμοι, και μια περίπλοκη προθέρμανση που σας κουράζει χάνει αυτόν τον στόχο.`},{title:`Πού ταιριάζει η διάταση`,text:`Οι μακριές παθητικές διατάσεις αμέσως πριν από εκρηκτική δραστηριότητα μπορούν να μειώσουν προσωρινά την απόδοση σε ορισμένες περιπτώσεις. Η σύντομη, άνετη διάταση δεν είναι αυτόματα βλαβερή, αλλά η δυναμική κινητικότητα και η σταδιακή εξάσκηση μετράνε συνήθως περισσότερο ακριβώς πριν από εργασία δύναμης, σπριντ ή άλματα. Μην διατείνεστε ποτέ μέσα σε πόνο για να φτάσετε κάποιο αυθαίρετο βάθος.`},{title:`Συνδυάζοντάς τα`,text:`Φτιάξτε την προθέρμανσή σας από τις κινήσεις της σημερινής συνεδρίας, το επίπεδο δεξιότητάς σας και τον χώρο σας: λίγα λεπτά ήπιας δραστηριότητας, και μετά ελαφριές εκδοχές της πρώτης σας άσκησης, με περισσότερη προετοιμασία όταν η εργασία είναι βαρύτερη ή ταχύτερη. Μετρήστε την προθέρμανση ως μέρος του χρόνου της συνεδρίας σας.`}];var r=[{label:`ACE 2026: πρακτικές οδηγίες για τη διάταση`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`Θέση του ACSM για το 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Βιβλιοθήκη ασκήσεων του ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var l={sections:i,sources:r};export{l as default,i as sections,r as sources};